#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Usage: scripts/setup-google-drive.sh [local|<ssh host>]...
#
# Creates the Google OAuth client the daemon uploads recordings with
# (upload_recording, docs/recording.md) and installs its JSON as
# google-drive-client.json in the daemon's config dir: on this machine
# ("local", the default) and/or on every ssh host named. The client is yours,
# in your own Google Cloud project; its secret is never printed.

CLIENT_FILE_NAME="google-drive-client.json"

# _client_ok FILE succeeds when FILE is an OAuth client JSON with an id and a
# secret (the console's download, or a flat {"client_id", "client_secret"}).
_client_ok() {
  python3 - "$1" <<'PY'
import json, sys
try:
    doc = json.load(open(sys.argv[1]))
except Exception as err:
    sys.exit(f"not JSON: {err}")
inner = doc.get("installed") or doc.get("web") or doc
if not (inner.get("client_id") and inner.get("client_secret")):
    sys.exit("no client_id / client_secret in it")
PY
}

# _install_client FILE DEST copies FILE into the daemon's config dir on DEST
# ("local" or an ssh host), readable by the owner only.
_install_client() {
  local file="$1" dest="$2"
  if [[ "$dest" == "local" ]]; then
    local dir="${XDG_CONFIG_HOME:-$HOME/.config}/mcp-midi-controller"
    mkdir -p "$dir"
    install -m 600 "$file" "$dir/$CLIENT_FILE_NAME"
    printf '  %s✓ installed%s %s\n' "$GREEN" "$RESET" "$dir/$CLIENT_FILE_NAME"
  else
    # shellcheck disable=SC2029  # the remote shell expands its own $HOME
    ssh "$dest" 'umask 077; d="${XDG_CONFIG_HOME:-$HOME/.config}/mcp-midi-controller"; mkdir -p "$d" && cat > "$d/'"$CLIENT_FILE_NAME"'" && chmod 600 "$d/'"$CLIENT_FILE_NAME"'"' < "$file"
    printf '  %s✓ installed%s %s:~/.config/mcp-midi-controller/%s\n' "$GREEN" "$RESET" "$dest" "$CLIENT_FILE_NAME"
  fi
}

# visit URL shows a page's address and opens it in the browser, without
# waiting for the opener: where no browser is running yet, xdg-open starts one
# and only returns when that browser is closed. Where setsid exists the opener
# runs in a session of its own, so Ctrl-C in the wizard does not reach the
# browser; elsewhere (macOS, whose open returns at once) it runs in the
# background, where a script's Ctrl-C is ignored too.
visit() {
  local url="$1" opener=""
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  for opener in wslview explorer.exe xdg-open open; do
    command -v "$opener" >/dev/null 2>&1 || continue
    if command -v setsid >/dev/null 2>&1; then
      setsid -f "$opener" "$url" </dev/null >/dev/null 2>&1 || true
    else
      ( "$opener" "$url" </dev/null >/dev/null 2>&1 & )
    fi
    return 0
  done
  warn "no browser opener here: open that address yourself"
}

run_wizard() {

TOTAL_STAGES=6
local dests=("$@")
(( ${#dests[@]} )) || dests=(local)
local q="" newest=""

banner "Google Drive for mcp-midi-controller: your own OAuth client"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "A Google Cloud project"
say "The client lives in a Google Cloud project of your own. Use an existing"
say "one or create one now (no billing account is needed for the Drive API)."
step "Sign in with the Google account whose Drive the recordings go to."
step "Project name: anything, e.g. \"mcp-midi-controller\". Click Create."
step "Copy the Project ID: it is shown under the name field while creating,"
say "  and later in the project picker at the top (not the project number)."
visit "https://console.cloud.google.com/projectcreate"
say "When the project exists, come back here."
ask GDRIVE_PROJECT_ID "Paste the Project ID, then Enter:"
q="?project=${GDRIVE_PROJECT_ID}"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Enable the Google Drive API"
step "Check the project named at the top is ${GDRIVE_PROJECT_ID}."
step "Click Enable and wait until the page shows \"API Enabled\" / Manage."
visit "https://console.cloud.google.com/apis/library/drive.googleapis.com${q}"
pause "Enabled? Press Enter for the next stage"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Register the app (the consent screen)"
say "Google shows this app's name when you approve the daemon later."
step "Click \"Get started\"."
step "App Information: App name e.g. \"mcp-midi-controller\", User support"
step "email: your address. Next."
step "Audience: External. Next."
step "Contact Information: your address. Next."
step "Finish: tick the Google API Services User Data Policy box. Continue,"
step "then Create."
note "No logo, no scopes to add: the daemon asks for the one scope it needs"
note "(drive.file: only the files it creates itself) when you approve it."
visit "https://console.cloud.google.com/auth/overview${q}"
pause "Created? Press Enter for the next stage"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Publish the app"
say "While an app is in \"Testing\", Google ends its sign-in after 7 days and"
say "the daemon would ask you to approve it again every week. \"In production\""
say "the sign-in stays. With only the drive.file scope and no logo there is no"
say "review to pass, and nobody else can use the client without its secret."
step "Under \"Publishing status\" click \"Publish app\", then Confirm."
step "The status now reads \"In production\"."
visit "https://console.cloud.google.com/auth/audience${q}"
pause "In production? Press Enter for the next stage"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Create the OAuth client"
say "The daemon has no browser of its own, so it signs in the way a TV does:"
say "it shows a code and you enter it on any device. That needs this client type."
step "Click \"Create client\"."
step "Application type: \"TVs and Limited Input devices\"."
step "Name: e.g. \"mcp-midi-controller daemon\". Click Create."
step "In the \"OAuth client created\" dialog click \"Download JSON\"."
warn "Google shows the client secret only now: download before closing the dialog."
visit "https://console.cloud.google.com/auth/clients${q}"
pause "Downloaded? Press Enter for the last stage"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Install the client file"
say "It goes into the daemon's config dir as ${CLIENT_FILE_NAME} (owner-only): ${dests[*]}"
# shellcheck disable=SC2012  # file names from the console have no newlines
newest=$(ls -t "$HOME"/Downloads/client_secret_*.json 2>/dev/null | head -n1 || true)
[[ -n "$newest" ]] && note "newest download: $newest"
while :; do
  read -e -r -p "  ${BOLD}Path of the downloaded JSON${RESET}${newest:+ [Enter takes the newest]}: " GDRIVE_CLIENT_JSON || exit 1
  [[ -z "$GDRIVE_CLIENT_JSON" && -n "$newest" ]] && GDRIVE_CLIENT_JSON="$newest"
  GDRIVE_CLIENT_JSON="${GDRIVE_CLIENT_JSON/#\~/$HOME}"
  if [[ ! -f "$GDRIVE_CLIENT_JSON" ]]; then warn "no such file: $GDRIVE_CLIENT_JSON"; continue; fi
  if _client_ok "$GDRIVE_CLIENT_JSON"; then break; fi
  warn "that is not an OAuth client file; pick the JSON the dialog downloaded"
done
for dest in "${dests[@]}"; do
  _install_client "$GDRIVE_CLIENT_JSON" "$dest" || { SKIPPED+=("install on $dest: copy $GDRIVE_CLIENT_JSON to its config dir as $CLIENT_FILE_NAME (chmod 600)"); warn "could not install on $dest"; }
done
if confirm "Delete the downloaded copy ($GDRIVE_CLIENT_JSON)?"; then
  rm -f "$GDRIVE_CLIENT_JSON"
fi

finish
say "Next: the daemon's connect_google_drive tool shows a code and a link."
say "Open the link, enter the code, approve. After that upload_recording works."
printf '\n'
}

run_wizard "$@"; exit
